/**
 * Permanent reference numbers (A7 / M3).
 *
 * Generated by `app.next_reference` in the caller's transaction. The TypeScript
 * catalog is the list of kinds and the format rules; PostgreSQL is the source
 * of uniqueness.
 */

export const YEARLESS_REFERENCE_KINDS = ['VND'] as const;
export type YearlessReferenceKind = (typeof YEARLESS_REFERENCE_KINDS)[number];

export const REFERENCE_KINDS = [
  'REQ',
  'PR',
  'PAY',
  'TRF',
  'GRN',
  'INV',
  'EMP',
  'DOC',
  'SEAL',
  'JNL',
  'BUD',
  'VND',
  'CUS',
  'SO',
  'PRD',
  'PRL',
  'LV',
  'VAC',
  'ICT',
  'ARI',
  'BILL',
  'INC',
  'EXP',
  'RCT',
  'RPT',
  'CASE',
  'IST',
  'ITR',
  'IAD',
  'CNT',
  'DSP',
  'SRN',
  'ORG',
  'MIN',
  'RSP',
  'DEC',
  'DISC',
  'TRN',
  'DEL',
] as const;

export type ReferenceKind = (typeof REFERENCE_KINDS)[number];

export function isReferenceKind(value: string): value is ReferenceKind {
  return (REFERENCE_KINDS as readonly string[]).includes(value);
}

export function isYearlessReferenceKind(kind: string): boolean {
  return (YEARLESS_REFERENCE_KINDS as readonly string[]).includes(kind);
}

/** Formats a kind + sequence the same way `app.next_reference` does. */
export function formatReferenceNumber(kind: ReferenceKind, sequence: number, year: number): string {
  const padded = String(sequence).padStart(6, '0');
  if (isYearlessReferenceKind(kind)) return `${kind}-${padded}`;
  return `${kind}-${year}-${padded}`;
}

/** Seeded search/timeline fixtures (M3). Stable so tests can look them up. */
export const YFZ_SEARCH_RECORD_ID = '00000000-0000-4000-8000-000000000101';
export const DMA_SEARCH_RECORD_ID = '00000000-0000-4000-8000-000000000102';
export const TIMELINE_SUBJECT_ID = '00000000-0000-4000-8000-000000000110';

/** M4 milling-machine fixture. Same id as the YFZ search row so the reference stays unique. */
export const PR_2026_000184_SUBJECT_ID = YFZ_SEARCH_RECORD_ID;
export const PR_2026_000184 = 'PR-2026-000184';
